            for (auto [v, eid] : adj[u]) {
                if (eid == pe) continue;
                if (tin[v]) low[u] = min(low[u], tin[v]);
                else {
                    par_u[v] = u;
                    par_e[v] = eid;
                    dfs(v, eid);
                    low[u] = min(low[u], low[v]);
                }
            }
        };
        dfs(a, -1);
        int ans = 0, cur = b;
        while (cur != a) {
            int p = par_u[cur];
            if (low[cur] > tin[p]) ans++;
            cur = p;
        }
        cout << ans << '\n';
    }
    return 0;
}

