    }
    void add_range(int l, int r, long long v) {
        add_pt(l, v);
        add_pt(r + 1, -v);
    }
    long long get(int i) const {
        long long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, q;
    cin >> n >> m >> q;
    vector<vector<int>> yards(n + 1);
    for (int j = 1; j <= m; j++) {
        int o; cin >> o;
        yards[o].push_back(j);
    }
    vector<long long> req(n + 1);
    for (int i = 1; i <= n; i++) cin >> req[i];
