    // Find one shortest BFS path A->B; any vertex separating A and B MUST lie on this path!
    // Test deleting each internal vertex on that path via BFS -> O(Q * (N + M)) worst-case on chains!
    vector<int> par(n + 1, 0), vis(n + 1, 0);
