            for (int v : g[u]) if (vis[v] != stamp) {
                vis[v] = stamp;
                par[v] = u;
                qv.push_back(v);
            }
        }
        vector<int> cands;
        for (int x = par[b]; x != a && x != 0; x = par[x]) cands.push_back(x);
        int ans = 0;
        for (int ban : cands) {
            ++stamp;
            vis[a] = stamp;
            vis[ban] = stamp;
            qv.assign(1, a);
            bool reach = false;
            for (size_t i = 0; i < qv.size(); i++) {
                int u = qv[i];
