            if (bpos[b] < pos) {
                swap(bvec[b], x);
                swap(bpos[b], pos);
            }
            x ^= bvec[b];
        }
        for (auto [l, id] : qs[r]) {
            int dim = 0;
            for (int b = 0; b < P; b++) if (bpos[b] >= l) dim++;
            int free_vars = (r - l + 1) - dim;
