                g0[p] += max(new_dp.first, new_dp.second) - max(old_dp.first, old_dp.second);
                g1[p] += new_dp.first - old_dp.first;
            }
            u = p;
        }
        cout << max(dp0[1], dp1[1]) << '\n';
    }
    return 0;
}

