        if (pos <= mid) set_point(u << 1, l, mid, pos, val);
        else set_point(u << 1 | 1, mid + 1, r, pos, val);
        mx[u] = max(mx[u << 1], mx[u << 1 | 1]);
    }
    void add_range(int u, int l, int r, int ql, int qr, long long val) {
